# test simple aggregate formulas modulo n
funcs={
 'sum_hc':lambda o,m:sum(c+h for c,h,x in o),
 'sum_hx':lambda o,m:sum(h*x for c,h,x in o),
 'sum_cx':lambda o,m:sum(c*x for c,h,x in o),
 'prod_h':lambda o,m:__import__('math').prod(h for c,h,x in o),
 'prod_c':lambda o,m:__import__('math').prod(c for c,h,x in o),
 'prod_x':lambda o,m:__import__('math').prod(x for c,h,x in o),
 'sum_sq_h':lambda o,m:sum(h*h for c,h,x in o),
 'sum_sq_x':lambda o,m:sum(x*x for c,h,x in o),
 'xor_h':lambda o,m:__import__('functools').reduce(int.__xor__,[h for c,h,x in o]),
 'xor_c':lambda o,m:__import__('functools').reduce(int.__xor__,[c for c,h,x in o]),
 'xor_x':lambda o,m:__import__('functools').reduce(int.__xor__,[x for c,h,x in o]),
}
for n in (2,3):
 rr=[r for r in records if len(r[0])==n]
 print('n=',n)
 for name,f in funcs.items():
  for a in range(n):
   for b in range(n):
    if all((a*m+b*f(o,m))%n==l for o,m,l in rr):print(name,a,b)
 # formulas direct no m
 for name,f in funcs.items():
  for b in range(n):
   if all((f(o,m)+b)%n==l for o,m,l in rr): print('direct',name,b)

